        t.exec("goto-goUpToSanfewWithMeat", t.player.goto_tile, 2903, 3428, 0)
        store_in_and_up("goUpToSanfewWithMeat")
        t.exec("talkToSanfewWithMeat", t.player.talk_to, "sanfew", 1)
