        t.ticks(3)
        t.quest.expect_complete()

        -- Reward checks -- the quest's actual reward, not just its completion (H2, docs/QUEST_SUITE_KIT.md).
        t.check("reward.herblore", t.skill.expect_gain("herblore", 250, reward_before))

        t.finish(0)
    end,
}
